    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        if len(original) == 1:
            # For n=1, any value in [min, max] works.
            return max(bounds[0][1], bounds[0][1]) - min(bounds[0][0], bounds[0][1]) + 1

