class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n = len(s)
        m = len(t)

        # If either string is empty, the longest palindrome is 1 (single character)
        if n == 0 or m == 0:
            return 1

        # Precompute palindrome counts between s[i:j] and t[j:m]
        # dp_s[i][j] = max length of palindrome formed by s[i:j] + t[j:m]
        # dp_s[i][j] = 2 * dp_s[i+1][j] + 1 if s[i:j] == reverse(t[j:m])
        #               else max(dp_s[i+1][j], dp_s[i][j-1])

        dp_s = [[0] * m for _ in range(n)]

        # Precompute reverse of t
        t_rev = t[::-1]

        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    # Check if s[i:j+1] == t[j:m]
                    if s[i:j+1] == t[j:m]:
                        dp_s[i][j] = 2 * dp_s[i+1][j] + 1
                    else:
                        dp_s[i][j] = max(dp_s[i+1][j], dp_s[i][j-1])
                else:
                    dp_s[i][j] = 1

        # Find the maximum palindrome length using t_rev
        ans = 1
        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    if s[i:j+1] == t_rev[j:m]:
                        ans = max(ans, 2 * dp_s[i+1][j] + 1)
                    else:
                        ans = max(ans, dp_s[i][j])
                else:
                    ans = max(ans, dp_s[i][j])

        return ans
